class Customer {
  constructor(public loyaltyLevel: number) {}
}

class Order {
  total: number;
  constructor(public customer: Customer, total: number) { this.total = total }
  applyLoyaltyDiscount() { if (this.customer.loyaltyLevel > 3) this.total *= 0.9 }
}

/* Version A */
class Order {
  constructor(public customer: Customer, public total: number) {}
  calculateDiscount() { if (this.customer.loyaltyLevel > 3) return this.total * 0.1; return 0 }
}

/* Version B */
class Customer {
  constructor(public loyaltyLevel: number) {}
  discountFor(orderTotal: number) { if (this.loyaltyLevel > 3) return orderTotal * 0.1; return 0 }
}
